const {test}=require('node:test'); const assert=require('node:assert/strict');
const {poll}=require('./poll-alerts.cjs');
function fixture(alerts=[]){let data;const outputs={};return {args:{github:{paginate:async()=>alerts,rest:{dependabot:{listAlertsForRepo(){}}}},context:{sha:'source-head',repo:{owner:'example',repo:'example'}},core:{setOutput:(k,v)=>outputs[k]=v,summary:{addRaw(){},async write(){}}},fs:{mkdirSync(){},writeFileSync:(p,v)=>data=JSON.parse(v)},coverage:{status:'verified',sha:'source-head',readback:{'uv.lock':{count:1}}},eventName:'schedule',schedule:'0 3 * * *'},outputs,get data(){return data}};}
test('no alert poll skips inference but daily cadence admits',async()=>{const f=fixture();await poll(f.args);assert.equal(f.outputs.admit,'false');f.args.schedule='0 9 * * *';await poll(f.args);assert.equal(f.outputs.admit,'true');});
test('advisory admission preserves package evidence and drops descriptions',async()=>{const f=fixture([{number:1,dependency:{package:{ecosystem:'pip',name:'example'},manifest_path:'uv.lock'},security_advisory:{ghsa_id:'GHSA-example',published_at:'2026-10-03',description:'untrusted'},security_vulnerability:{severity:'low',vulnerable_version_range:'<2'},created_at:'2026-10-03',html_url:'https://github.com/example/example/security/dependabot/1'}]);await poll(f.args);assert.equal(f.outputs.admit,'true');assert.equal(f.data.alerts[0].fixed,null);assert.equal(f.data.alerts[0].description,undefined);});
test('API failures fail closed including daily routine',async()=>{const f=fixture();f.args.github.paginate=async()=>{throw Error('403')};await assert.rejects(()=>poll(f.args),/403/);assert.equal(f.outputs.admit,undefined);});

test('zero alerts cannot admit without exact-source coverage',async()=>{const f=fixture();f.args.schedule='0 9 * * *';delete f.args.coverage;await assert.rejects(()=>poll(f.args),/coverage/);assert.equal(f.outputs.admit,undefined);f.args.coverage={status:'verified',sha:'previous-head',readback:{'uv.lock':{count:1}}};await assert.rejects(()=>poll(f.args),/coverage/);});
